PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  # Risk tolerance (string or via reference)
  OPTIONAL { ?investor wm:riskTolerance ?rtString . }
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtNode .
    ?rtNode rdfs:label ?rtLabel .
  }
  BIND(COALESCE(?rtString, ?rtLabel) AS ?riskLabel)
  FILTER(CONTAINS(LCASE(STR(?riskLabel)), "conservative"))

  # Time horizon (string or via reference)
  OPTIONAL { ?investor wm:timeHorizon ?thString . }
  OPTIONAL {
    ?investor wm:hasTimeHorizon ?thNode .
    ?thNode rdfs:label ?thLabel .
  }
  BIND(COALESCE(?thString, ?thLabel) AS ?horizonLabel)
  FILTER(CONTAINS(LCASE(STR(?horizonLabel)), "short-term"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?marketScenario (COUNT(?sr) AS ?recordCount)
WHERE {
  ?sr rdf:type wm:ScenarioRebalancing .
  OPTIONAL { ?sr wm:hasMarketScenario ?ms . }
  OPTIONAL { ?ms rdfs:label ?msLabel . }
  OPTIONAL { ?sr wm:scenario ?scenarioLiteral . }
  BIND(COALESCE(?msLabel, ?scenarioLiteral, "NULL") AS ?marketScenario)
}
GROUP BY ?marketScenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (SUM(xsd:decimal(?totalInv)) AS ?totalInvestment) WHERE {
  ?sa rdf:type wm:SectorAllocation .
  ?sa wm:totalInvestment ?totalInv .
  OPTIONAL {
    ?sa wm:hasSector ?sector .
    OPTIONAL { ?sector rdfs:label ?label . }
  }
  OPTIONAL {
    ?sa wm:sector ?sectorLiteral .
  }
  BIND(COALESCE(?label, ?sectorLiteral) AS ?sectorName)
  FILTER(BOUND(?sectorName))
}
GROUP BY ?sectorName
ORDER BY DESC(?totalInvestment)
LIMIT 5

