PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskGroup
       (AVG(?goalProgress) AS ?avgGoalProgress)
       (AVG(?riskScore) AS ?avgRiskScore)
       (SUM(?holdingValue) AS ?totalHoldingValue)
WHERE {
  ?investor rdf:type wm:Investor .

  # Determine risk‑tolerance label
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtEntity .
    OPTIONAL { ?rtEntity rdfs:label ?rtLabel . }
  }
  OPTIONAL { ?investor wm:riskTolerance ?rtLiteral . }
  BIND( COALESCE(?rtLabel, ?rtLiteral, "NULL") AS ?riskGroup )

  # Average goal progress per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?pg)) AS ?goalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?pg .
    }
    GROUP BY ?investor
  }

  # Average risk score per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?investor .
      ?ph wm:riskScore ?rs .
    }
    GROUP BY ?investor
  }

  # Total holding value per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?hv)) AS ?holdingValue)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?hv .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskGroup

