SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER EXISTS {
    ?cashFlow rdf:type wm:CashFlow ;
              wm:cashFlowOfInvestor ?investor ;
              wm:date ?cashDate .
    FILTER(STRSTARTS(LCASE(STR(?cashDate)), "2025"))
  }

  FILTER EXISTS {
    ?holding rdf:type wm:PortfolioHolding ;
             wm:heldByInvestor ?investor ;
             wm:purchaseDate ?purchaseDate ;
             wm:returnsPct ?returnsPct .
    FILTER(STRSTARTS(LCASE(STR(?purchaseDate)), "2025"))
    FILTER(xsd:decimal(?returnsPct) < 0)
  }

  FILTER EXISTS {
    ?goal rdf:type wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }
}

