SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Positive total shortfall
  {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?totalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
      ?goal wm:shortfall ?sf .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?sf)) > 0)
  }

  # Net negative cash flow
  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?invCf .
      ?invCf wm:investorId ?investorId .
      ?cf wm:amount ?amt .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amt)) < 0)
  }

  # At least one De‑risking rebalancing action
  FILTER EXISTS {
    ?ra rdf:type wm:RebalancingAction .
    ?ra wm:rebalancingActionOfInvestor ?invRa .
    ?invRa wm:investorId ?investorId .
    ?ra wm:action ?action .
    FILTER(CONTAINS(LCASE(STR(?action)), "de-risking"))
  }
}

