  OPTIONAL {
    ?investor wm:hasSegment ?segmentNode .
    ?segmentNode rdfs:label ?segmentLabel .
  }
  OPTIONAL { ?investor wm:category ?categoryLiteral . }
  OPTIONAL {
    ?investor wm:hasCategory ?categoryNode .
    ?categoryNode rdfs:label ?categoryLabel .
  }
  BIND(COALESCE(?segmentLiteral, ?segmentLabel, "NULL") AS ?segment)
  BIND(COALESCE(?categoryLiteral, ?categoryLabel, "NULL") AS ?category)
}
GROUP BY ?segment ?category
ORDER BY ?segment ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceGroup ?goalBucket (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT ?investor (COUNT(?goal) AS ?goalCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
    }
    GROUP BY ?investor
  }
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
  BIND( COALESCE(?riskTol, "NULL") AS ?riskToleranceGroup )
  BIND(
    IF(?goalCount = 1, "One",
      IF(?goalCount = 2, "Two",
        IF(?goalCount = 3, "Three", "FourOrMore")
      )
    ) AS ?goalBucket
  )
}
GROUP BY ?riskToleranceGroup ?goalBucket
ORDER BY ?riskToleranceGroup ?goalBucket

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceGroup ?cashFlowSource (COUNT(?cashFlow) AS ?transactionCount)
WHERE {
  ?cashFlow rdf:type wm:CashFlow .
  ?cashFlow wm:cashFlowOfInvestor ?investor .
  ?investor rdf:type wm:Investor .

  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtObj .
    OPTIONAL { ?rtObj rdfs:label ?rtLabel . }
  }
  OPTIONAL { ?investor wm:riskTolerance ?rtLiteral . }
  BIND (COALESCE(?rtLabel, ?rtLiteral, "NULL") AS ?riskToleranceGroup)

  OPTIONAL {
    ?cashFlow wm:hasCashFlowSource ?srcObj .
    OPTIONAL { ?srcObj rdfs:label ?srcLabel . }
  }
  OPTIONAL { ?cashFlow wm:source ?srcLiteral . }
  BIND (COALESCE(?srcLabel, ?srcLiteral, "NULL") AS ?cashFlowSource)
}
GROUP BY ?riskToleranceGroup ?cashFlowSource

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgProgress ?riskScore
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  {
    ?investor wm:category ?catLiteral .
    FILTER(CONTAINS(LCASE(STR(?catLiteral)), "moderate"))
  } UNION {
    ?investor wm:hasCategory ?catObj .
    ?catObj rdfs:label ?catLabel .
    FILTER(CONTAINS(LCASE(STR(?catLabel)), "moderate"))
  }

  ?investor wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScoreRaw .
  BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore) .
  FILTER(?riskScore > 60)

  {
    SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?avgProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?progress)) < 30)
  }
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?riskBand (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor rdf:type wm:Investor .
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:returnsPct ?ret .
      FILTER(xsd:decimal(?ret) < 0)
    }
  }
  OPTIONAL {
    ?investor wm:hasCategory ?catObj .
    OPTIONAL { ?catObj rdfs:label ?catLabel . }
    BIND(COALESCE(?catLabel, STR(?catObj)) AS ?categoryTmp)
  }
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?riskObj .
    OPTIONAL { ?riskObj rdfs:label ?riskLabel . }
    BIND(COALESCE(?riskLabel, STR(?riskObj)) AS ?riskTmp)
  }
  BIND(COALESCE(?categoryTmp, "NULL") AS ?category)
  BIND(COALESCE(?riskTmp, "NULL") AS ?riskBand)
}
GROUP BY ?category ?riskBand

