SELECT ?sectorLabel (COALESCE(?holdingSum, xsd:decimal(0)) AS ?totalHoldingValue) (COALESCE(?allocationSum, xsd:decimal(0)) AS ?totalSectorAllocation) WHERE {
  {
    SELECT DISTINCT ?sectorKey WHERE {
      {
        ?h rdf:type wm:PortfolioHolding .
        OPTIONAL { ?h wm:hasSector ?s . }
        OPTIONAL { ?h wm:sector ?sLit . }
        BIND(COALESCE(?s, ?sLit) AS ?sectorKey) .
        FILTER(BOUND(?sectorKey))
      }
      UNION
      {
        ?a rdf:type wm:SectorAllocation .
        OPTIONAL { ?a wm:hasSector ?s . }
        OPTIONAL { ?a wm:sector ?sLit . }
        BIND(COALESCE(?s, ?sLit) AS ?sectorKey) .
        FILTER(BOUND(?sectorKey))
      }
    }
  }
  OPTIONAL {
    SELECT ?sectorKey (SUM(xsd:decimal(?val)) AS ?holdingSum) WHERE {
      ?h rdf:type wm:PortfolioHolding .
      OPTIONAL { ?h wm:hasSector ?s . }
      OPTIONAL { ?h wm:sector ?sLit . }
      BIND(COALESCE(?s, ?sLit) AS ?sectorKey) .
      ?h wm:currentValue ?val .
    }
    GROUP BY ?sectorKey
  }
  OPTIONAL {
    SELECT ?sectorKey (SUM(xsd:decimal(?alloc)) AS ?allocationSum) WHERE {
      ?a rdf:type wm:SectorAllocation .
      OPTIONAL { ?a wm:hasSector ?s . }
      OPTIONAL { ?a wm:sector ?sLit . }
      BIND(COALESCE(?s, ?sLit) AS ?sectorKey) .
      ?a wm:totalInvestment ?alloc .
    }
    GROUP BY ?sectorKey
  }
  OPTIONAL { ?sectorKey rdfs:label ?sectorLabel . }
}
ORDER BY ?sectorLabel

