SELECT ?investorId ?investorName (SUM(xsd:decimal(?amount)) AS ?totalWithdrawal)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?maxRisk)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
    HAVING (MAX(xsd:decimal(?riskScore)) > 50)
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?prog)) AS ?avgProg)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:progressPct ?prog .
    }
    GROUP BY ?investorId
