    OPTIONAL { ?riskTol rdfs:label ?riskTolLabel . }
  }

  OPTIONAL {
    ?goal wm:hasInvestmentGoalType ?goalType .
    OPTIONAL { ?goalType rdfs:label ?goalTypeLabel . }
  }

  BIND(COALESCE(?riskTolLabel, "NULL") AS ?riskTolerance)
  BIND(COALESCE(?goalTypeLabel, "NULL") AS ?goalContext)
}
GROUP BY ?riskTolerance ?goalContext

