SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  # Aggressive risk tolerance (direct property or via RiskTolerance object)
  OPTIONAL { ?investor wm:riskTolerance ?rtStr1 . }
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtObj .
    ?rtObj wm:riskTolerance ?rtStr2 .
  }
  BIND( COALESCE(?rtStr1, ?rtStr2) AS ?rtVal )
  FILTER( CONTAINS(LCASE(STR(?rtVal)), "aggressive") )

  # At least one Momentum-driven rebalancing logic
  FILTER EXISTS {
    ?ra rdf:type wm:RebalancingAction .
    ?ra wm:rebalancingActionOfInvestor ?investor .
    ?ra wm:hasRebalancingLogic ?logic .
    OPTIONAL { ?logic rdfs:label ?logicLabel . }
    OPTIONAL { ?logic wm:logic ?logicName . }
    BIND( COALESCE(?logicLabel, ?logicName) AS ?logicVal )
    FILTER( CONTAINS(LCASE(STR(?logicVal)), "momentum") )
  }
}

