PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (AVG(?allocAvg) AS ?avgAllocationPct) (AVG(?returnAvg) AS ?avgHoldingReturnPct)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:category ?cat . }
  BIND(COALESCE(?cat, "NULL") AS ?category)

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?alloc)) AS ?allocAvg)
    WHERE {
      ?investor wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?alloc .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?ret)) AS ?returnAvg)
    WHERE {
      ?investor wm:hasHolding ?hold .
      ?hold wm:returnsPct ?ret .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?category

