SELECT ?riskTolerance 
       (SUM(xsd:decimal(COALESCE(?depositAmt, 0))) AS ?totalDeposit) 
       (SUM(xsd:decimal(COALESCE(?rebalanceAmt, 0))) AS ?totalRebalancing)
WHERE {
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?riskTolerance . }
  BIND(COALESCE(?riskTolerance, "NULL") AS ?riskTolerance)

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?depositAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:type ?cfType .
      FILTER(LCASE(STR(?cfType)) = "deposit") .
      ?cf wm:amount ?amt .
      ?cf wm:cashFlowOfInvestor ?inv .
