PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  # Investor must have Gold category (literal or via Category instance)
  FILTER EXISTS {
    { ?investor wm:category ?invCat .
      FILTER(LCASE(STR(?invCat)) = "gold")
    } UNION
    { ?investor wm:hasCategory ?cat .
      ?cat rdfs:label ?catLabel .
      FILTER(LCASE(STR(?catLabel)) = "gold")
    }
  }

  # Investor must hold a Gold holding (literal or via Category instance)
  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    { ?holding wm:category ?holdCat .
      FILTER(LCASE(STR(?holdCat)) = "gold")
    } UNION
    { ?holding wm:hasCategory ?hcat .
      ?hcat rdfs:label ?hcatLabel .
      FILTER(LCASE(STR(?hcatLabel)) = "gold")
    }
  }

  # Link to PortfolioHealth (either direction) and filter riskScore > 60
  {
    ?investor wm:hasPortfolioHealth ?ph .
  } UNION {
    ?ph wm:healthOfInvestor ?investor .
  }
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60)
}

