PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolLabel (SUM(?netCash) AS ?netCashFlow) (AVG(?goalProgress) AS ?avgGoalProgressPct)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
  BIND( COALESCE(?riskTol, "NULL") AS ?riskTolLabel ) .

  {
    SELECT ?investor (SUM(?signedAmt) AS ?netCash) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amount .
      OPTIONAL { ?cf wm:type ?cfType . }
      BIND(
        IF(BOUND(?cfType) && LCASE(STR(?cfType)) = "inflow",
           xsd:decimal(?amount),
           IF(BOUND(?cfType) && LCASE(STR(?cfType)) = "outflow",
              -xsd:decimal(?amount),
              xsd:decimal(?amount)
           )
        ) AS ?signedAmt
      )
    } GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?investor
  }
}
GROUP BY ?riskTolLabel

