PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(?cf) AS ?transactionCount) (SUM(?amt) AS ?netAmount)
WHERE {
  {
    SELECT ?cf (SUBSTR(STR(COALESCE(?date, "NULL")),1,7) AS ?month) (COALESCE(xsd:decimal(?amount), 0) AS ?amt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      OPTIONAL { ?cf wm:date ?date . }
      OPTIONAL { ?cf wm:amount ?amount . }
    }
  }
}
GROUP BY ?month
ORDER BY ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (COUNT(?rebalanceId) AS ?actionCount) (AVG(?gap) AS ?avgAllocationGap)
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId ;
       wm:hasRebalancingAction ?ra .
  ?ra rdf:type wm:RebalancingAction ;
      wm:rebalanceId ?rebalanceId ;
      wm:currentAllocationPct ?currentPct ;
      wm:targetAllocationPct ?targetPct .
  BIND( (xsd:decimal(?targetPct) - xsd:decimal(?currentPct)) AS ?gap )
}
GROUP BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER EXISTS {
    ?cf rdf:type wm:CashFlow ;
        wm:cashFlowOfInvestor ?investor ;
        wm:type ?cfType .
    FILTER(CONTAINS(LCASE(STR(?cfType)), "withdrawal"))
  }

  FILTER EXISTS {
    ?goal rdf:type wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:progressPct ?progressPct .
    FILTER(xsd:decimal(?progressPct) < 25)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario
       ?avgCurrentAllocationPct
       ?avgNewAllocationPct
       ((?avgCurrentAllocationPct - ?avgNewAllocationPct) AS ?differencePct)
WHERE {
  {
    SELECT ?scenario (AVG(xsd:float(?curr)) AS ?avgCurrentAllocationPct)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenario ?scenario .
      ?sr wm:currentAllocationPct ?curr .
    }
    GROUP BY ?scenario
  }
  OPTIONAL {
    SELECT ?scenario (AVG(xsd:float(?new)) AS ?avgNewAllocationPct)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenario ?scenario .
      ?sr wm:newAllocationPct ?new .
    }
    GROUP BY ?scenario
  }
}
ORDER BY ?scenario

