SELECT DISTINCT ?investorId ?investorName
WHERE {
  {
    SELECT DISTINCT ?investor
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:type ?cfType .
      FILTER(LCASE(STR(?cfType)) = "withdrawal")
    }
  }
  {
    SELECT DISTINCT ?investor
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?investor .
      ?ra wm:action ?raAction .
      FILTER(LCASE(STR(?raAction)) = "sell")
    }
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?combinedAmount WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?cashTotal) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?raAmt)) AS ?rebalanceTotal) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?investor .
      ?ra wm:amount ?raAmt .
    } GROUP BY ?investor
  }

  BIND( (COALESCE(?cashTotal, xsd:decimal("0")) + COALESCE(?rebalanceTotal, xsd:decimal("0"))) AS ?combinedAmount )
}
ORDER BY DESC(?combinedAmount)
LIMIT 10

