    )
  }

  FILTER EXISTS {
    ?investor wm:hasScenarioRebalancing ?sr .
    ?sr rdf:type wm:ScenarioRebalancing .
    ?sr wm:scenario ?scenario .
    FILTER(CONTAINS(LCASE(STR(?scenario)), "flash crash"))
  }
}

