    ?reb wm:action ?rebAction .
    FILTER(LCASE(STR(?rebAction)) = "sell")
    { ?investor wm:hasRebalancingAction ?reb } UNION { ?reb wm:rebalancingActionOfInvestor ?investor }
  }
}

