      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?cfAmt .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:type ?cfType .
      FILTER(LCASE(STR(?cfType)) = "net")
