PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?totalScore WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmt)) AS ?cashFlowSum) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?cfAmt .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:type ?cfType .
      FILTER(LCASE(STR(?cfType)) = "net")
    } GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?raAmt)) AS ?rebalanceSum) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:amount ?raAmt .
      ?ra wm:rebalancingActionOfInvestor ?inv .
