      ?inv wm:investorId ?investorId .
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?curAlloc .
      BIND(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc)) AS ?allocChange)
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
    } GROUP BY ?investorId
  }
  BIND( (COALESCE(?cashFlowSum, 0) + COALESCE(?rebalanceSum, 0) + COALESCE(?scenarioChangeSum, 0)) AS ?totalScore )
}
ORDER BY DESC(?totalScore)
