      FILTER (STRSTARTS(?cfDate, "2025")) .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmt)) AS ?rebalanceAmount) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?invRA .
      ?invRA wm:investorId ?investorId .
      ?ra wm:amount ?rebAmt .
