PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalLabel 
       (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct) 
       (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall) 
       (AVG(xsd:decimal(?volatility)) AS ?avgVolatilityPct)
WHERE {
  ?ig rdf:type wm:InvestmentGoal .
  OPTIONAL { ?ig wm:investmentGoal ?investmentGoal . }
  OPTIONAL { ?ig wm:progressPct ?progressPct . }
  OPTIONAL { ?ig wm:shortfall ?shortfall . }
  OPTIONAL { ?ig wm:avgVolatilityPct ?volatility . }
  BIND(COALESCE(?investmentGoal, "NULL") AS ?goalLabel)
}
GROUP BY ?goalLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel ?totalHoldingValue ?totalAllocationPct
WHERE {
  {
    SELECT ?category ?categoryLabel (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:hasCategory ?category .
      ?category rdfs:label ?categoryLabel .
      ?holding wm:currentValue ?holdingValue .
    }
    GROUP BY ?category ?categoryLabel
  }
  {
    SELECT ?category ?categoryLabel (SUM(xsd:decimal(?allocPctSum)) AS ?totalAllocationPct)
    WHERE {
      {
        SELECT ?sector (SUM(xsd:decimal(?allocPct)) AS ?allocPctSum)
        WHERE {
          ?sectorAlloc rdf:type wm:SectorAllocation .
          ?sectorAlloc wm:hasSector ?sector .
          ?sectorAlloc wm:allocationPct ?allocPct .
        }
        GROUP BY ?sector
      }
      {
        SELECT DISTINCT ?sector ?category ?categoryLabel
        WHERE {
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:hasSector ?sector .
          ?holding wm:hasCategory ?category .
          ?category rdfs:label ?categoryLabel .
        }
      }
    }
    GROUP BY ?category ?categoryLabel
  }
}
ORDER BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel
       (AVG(?scenarioChange) AS ?avgScenarioAllocationChange)
       (AVG(?actionChange) AS ?avgRebalancingAllocationChange)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
  BIND(COALESCE(?timeHorizon, "NULL") AS ?timeHorizonLabel)

  OPTIONAL {
    SELECT ?investor ( (xsd:decimal(?scNew) - xsd:decimal(?scCurrent)) AS ?scenarioChange )
    WHERE {
      ?investor wm:hasScenarioRebalancing ?sc .
      ?sc rdf:type wm:ScenarioRebalancing .
      ?sc wm:currentAllocationPct ?scCurrent .
      ?sc wm:newAllocationPct ?scNew .
    }
  }

  OPTIONAL {
    SELECT ?investor ( (xsd:decimal(?actTarget) - xsd:decimal(?actCurrent)) AS ?actionChange )
    WHERE {
      ?investor wm:hasRebalancingAction ?ra .
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:currentAllocationPct ?actCurrent .
      ?ra wm:targetAllocationPct ?actTarget .
    }
  }
}
GROUP BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalId ?description ?targetAmount ?shortfall ?totalCashFlow ?avgCashFlow ?cashFlowCount
WHERE {
  ?ig rdf:type wm:InvestmentGoal ;
      wm:goalId ?goalId ;
      wm:description ?description ;
      wm:targetAmount ?targetAmount ;
      wm:shortfall ?shortfall ;
      wm:belongsToInvestor ?inv .

  ?inv rdf:type wm:Investor .

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) (AVG(xsd:decimal(?amt)) AS ?avgCashFlow) (COUNT(?cf) AS ?cashFlowCount)
    WHERE {
      ?cf rdf:type wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
  }
}
ORDER BY ?goalId

