SELECT ?source ?scenario (AVG(xsd:decimal(?allocChange)) AS ?avgAllocationChange) (SUM(xsd:decimal(?cashAmt)) AS ?totalCashAmount) (COUNT(?scenario) AS ?scenarioCount)
WHERE {
  {
    SELECT ?investor ?source (SUM(xsd:decimal(?amount)) AS ?cashAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:source ?source .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investor ?source
  }
  {
    SELECT ?investor ?scenario ( (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocChange )
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?investor .
      ?sr wm:scenario ?scenario .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?currAlloc .
    }
  }
}
GROUP BY ?source ?scenario

