  }

  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore) (AVG(xsd:decimal(?liquidityScoreVal)) AS ?liquidityScore)
    WHERE {
      ?health rdf:type wm:PortfolioHealth .
      ?health wm:riskScore ?riskScoreVal .
