  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue) WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:heldByInvestor ?investor .
      ?ph wm:currentValue ?currentValue .
    } GROUP BY ?investorId
  }
}
