PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel
       (AVG(?goalProgress) AS ?avgGoalProgressPct)
       (AVG(?holdingGain) AS ?avgHoldingGainPct)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
WHERE {
  ?investor rdf:type wm:Investor .

  # Resolve category label either from literal or from linked Category entity
  OPTIONAL {
    ?investor wm:category ?catLiteral .
  }
  OPTIONAL {
    ?investor wm:hasCategory ?catEntity .
    ?catEntity rdfs:label ?catLabel .
  }
  BIND(COALESCE(?catLabel, ?catLiteral, "NULL") AS ?categoryLabel)

  # Goal progress per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  # Holding gain per investor (using returnsPct as gain)
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?holdingGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investor
  }

  # Risk and liquidity scores per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
                     (AVG(xsd:decimal(?liquidityScoreVal)) AS ?liquidityScore)
    WHERE {
      ?health rdf:type wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:riskScore ?riskScoreVal ;
              wm:liquidityScore ?liquidityScoreVal .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?categoryLabel

