PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (SUM(COALESCE(?inflowAmt, 0)) AS ?totalInflow)
       (SUM(COALESCE(?outflowAmt, 0)) AS ?totalOutflow)
       (SUM(COALESCE(?shortfallAmt, 0)) AS ?totalShortfall)
       (SUM(COALESCE(?dividendAmt, 0)) AS ?totalDividends)
       (SUM(COALESCE(?taxAmt, 0)) AS ?totalTaxesPaid)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }

  OPTIONAL {
    ?cf rdf:type wm:CashFlow .
    ?cf wm:cashFlowOfInvestor ?investor .
    ?cf wm:type ?cfType .
    ?cf wm:amount ?cfAmt .
    BIND( IF( LCASE(STR(?cfType)) = "inflow", xsd:decimal(?cfAmt), 0 ) AS ?inflowAmt )
    BIND( IF( LCASE(STR(?cfType)) = "outflow", xsd:decimal(?cfAmt), 0 ) AS ?outflowAmt )
  }

  OPTIONAL {
    ?goal rdf:type wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?goal wm:shortfall ?sf .
    BIND( xsd:decimal(?sf) AS ?shortfallAmt )
  }

  OPTIONAL {
    ?hold rdf:type wm:PortfolioHolding .
    ?hold wm:heldByInvestor ?investor .
    OPTIONAL {
      ?hold wm:dividends ?div .
      BIND( xsd:decimal(?div) AS ?dividendAmt )
    }
    OPTIONAL {
      ?hold wm:taxesPaid ?tax .
      BIND( xsd:decimal(?tax) AS ?taxAmt )
    }
  }
}
