PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(?shortfall) AS ?avgShortfall)
       (SUM(?holdingValue) AS ?totalHoldingValue)
       (AVG(?maxAllocPct) AS ?avgAllocationConcentration)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
       (AVG(?diversificationScore) AS ?avgDiversificationScore)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?th . }
  BIND(COALESCE(?th, "NULL") AS ?timeHorizon)

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?sf)) AS ?shortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?sf .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cv)) AS ?holdingValue)
    WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:investorId ?investorId .
      ?hold wm:currentValue ?cv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (MAX(xsd:decimal(?allocPct)) AS ?maxAllocPct)
    WHERE {
      ?alloc rdf:type wm:SectorAllocation .
      ?alloc wm:investorId ?investorId .
      ?alloc wm:allocationPct ?allocPct .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?liq)) AS ?liquidityScore) (AVG(xsd:decimal(?div)) AS ?diversificationScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:liquidityScore ?liq .
      ?ph wm:diversificationScore ?div .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?timeHorizon

