PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(xsd:decimal(COALESCE(?cashFlowSum, 0))) AS ?totalCashFlow)
       (SUM(xsd:decimal(COALESCE(?rebalanceSum, 0))) AS ?totalRebalancingAmount)
       (SUM(xsd:decimal(COALESCE(?scenarioCount, 0))) AS ?scenarioChangeCount)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
       (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalMatchPct)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?cashFlowSum)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?raAmt)) AS ?rebalanceSum)
    WHERE {
      ?investor wm:hasRebalancingAction ?ra .
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:amount ?raAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (COUNT(?sr) AS ?scenarioCount)
    WHERE {
      ?investor wm:hasScenarioRebalancing ?sr .
      ?sr rdf:type wm:ScenarioRebalancing .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor ?riskScore ?goalMatchPct
    WHERE {
      ?investor wm:hasPortfolioHealth ?ph .
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:goalMatchPct ?goalMatchPct .
    }
  }
}
GROUP BY ?timeHorizon

