PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel 
       (SUM(xsd:decimal(?totalCashFlow)) AS ?cashFlowSum) 
       (SUM(xsd:decimal(?totalRebalanceAmount)) AS ?rebalanceSum) 
       (SUM(xsd:decimal(?scenarioCount)) AS ?scenarioTotal) 
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) 
       (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalMatchPct)
WHERE {
  # Investor and category
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:hasCategory ?cat .
  ?cat rdfs:label ?categoryLabel .

  # Cash flow aggregation per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?investorId
  }

  # Rebalancing amount aggregation per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?ra wm:amount ?rebAmount .
    } GROUP BY ?investorId
  }

  # Scenario rebalancing count per investor
  OPTIONAL {
    SELECT ?investorId (COUNT(?sr) AS ?scenarioCount) WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  # Portfolio health metrics per investor
  OPTIONAL {
    ?ph rdf:type wm:PortfolioHealth .
    ?ph wm:healthOfInvestor ?inv .
    ?inv wm:investorId ?investorId .
    ?ph wm:riskScore ?riskScore .
    ?ph wm:goalMatchPct ?goalMatchPct .
  }
}
