PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCashFlow ?avgProgress ?riskScore ?scenarioChange
WHERE {
  # Investor core
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Net cash flow aggregation
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # Average goal progress aggregation
  {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?avgProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?goal wm:progressPct ?progress .
    }
    GROUP BY ?investorId
  }

  # Risk score
  {
    SELECT ?investorId ?riskScore
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
  }

  # Scenario change (max absolute allocation change)
  {
    SELECT ?investorId (MAX(ABS(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc))) AS ?scenarioChange)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?investorId
  }

  FILTER (xsd:decimal(?totalCashFlow) > 100000000)
  FILTER (xsd:decimal(?avgProgress) < 25)
  FILTER (xsd:decimal(?riskScore) > 70)
  FILTER (xsd:decimal(?scenarioChange) > 20)
}
ORDER BY DESC(?totalCashFlow)

